#!/bin/zsh
# Visuels manquants de la proposition crossover v2 (chapitres sans image, Sacré Graal, Wabbajack).
# FLUX 3 Klein local, gratuit, passe par la file calcul-lourd. Relançable : saute ce qui existe. Usage : gen_crossover_c.sh [id…]
cd "$(dirname "$0")/../work/crossover" || exit 1
STL="hand-painted 2000s 2D point-and-click adventure game scene, painterly detailed backgrounds like classic adventure games, bold dark outlines, warm saturated colors, humorous storybook fantasy, characters with realistic adult proportions and ironic expressions, wide composition, no logo, no watermark, no frame"
ST="$STL, no text, no letters"
H="The hero is exactly the man from the first reference picture, same face, same blond ponytail, same horned iron Viking helmet, same fur-collared studded leather armor, same round wooden shield on his back, same brown kilt and fur-topped boots, same painted style."
typeset -A P R
P[r_sammax]="$H A sunny desert roadside attraction along a dusty highway: a giant wheel of yellow cheese as big as a house on a wooden platform under a big blank painted billboard, a vintage 1960s black-and-white police sedan parked nearby. Next to the hero stand a tall anthropomorphic brown dog detective walking upright in a grey suit and grey fedora hat, calm and deadpan, and a small hyperactive white rabbit-like creature with a huge toothy grin bouncing on the hero's shoulder. $ST"
P[r_indiana]="$H Inside an ancient overgrown jungle temple lit by torches: a small golden idol on a carved stone pedestal, a pit full of snakes in the foreground, spider webs, sunlight beams, a huge round stone boulder at the top of a ramp behind. A rugged archaeologist in a brown leather jacket and a battered brown fedora, a coiled whip at his belt, raises a warning hand, while the hero carefully holds a big wheel of yellow cheese with both hands, ready to swap it with the idol. $ST"
P[r_retour]="$H A small 1950s American town square at night in a thunderstorm: a courthouse with a big lit clock tower, lightning in the sky, a long cable stretched from the clock tower down to a lamp post. In the street stands an old wooden medieval cart completely covered with shiny stainless steel panels, two doors opened upward like wings, glowing blue coils, harnessed to a brown horse. A wild-haired old scientist in a white lab coat waves both arms excitedly at the hero. $ST"
P[r_kaamelott]="$H A medieval castle hall with a big round wooden table, red banners and torches. A weary king with a short beard and a simple gold crown sits at the table, his head resting on one hand, while two dim-witted knights grin vacantly: one lanky with a blank stare, one stout chewing a chicken leg. The hero explains something with big gestures. A banquet of ham, sausages, bread and cheese covers the table. $ST"
P[r_graal]="$H A misty green English countryside with a ruined castle on a hill. On the path, three very tall knights in long dark robes with enormous helmets topped with deer antlers block the way, pointing imperiously. Behind them, a knight in silver armor walks along banging two coconut halves together as if riding an invisible horse. The hero holds a small potted shrub. In front of a dark cave, a small fluffy white rabbit with glowing red eyes sits menacingly. $ST"
P[r_conan]="$H A barren snowy plain under a grey sky with a huge wooden millstone wheel with long wooden spokes turning around a stone pillar. A very muscular barbarian with long black hair, a fur loincloth and fur boots pushes one spoke beside the hero, who pushes another one, both straining. In the sky, a long white furry flying dragon with a friendly dog-like face and pearly scales soars happily. On the horizon, a dark swirling void of nothingness eats the landscape. $ST"
P[r_stranger]="$H A cozy 1980s suburban living room at night: wood-paneled walls with the alphabet letters A to Z hand-painted in black on the wallpaper under strings of colorful Christmas lights, a few bulbs glowing. A floral sofa, a box TV. Three kids with bowl haircuts holding walkie-talkies stare at the hero. The wallpaper is torn open and a tall slimy creature whose head opens like the petals of a flower pokes out of the wall. $STL"
P[r_twinpeaks]="$H A strange dreamlike room surrounded on all sides by heavy red velvet curtains, a black-and-white zigzag chevron floor, an antique white Greek statue of a woman, two black armchairs and a floor lamp. A small man in a red suit dances. In one armchair lounges the mad prince from the second reference picture, same face, same coat split purple and red, perfectly at home, holding a cup of coffee and a slice of cherry pie. The hero stands confused in the middle. $ST"
R[r_twinpeaks]="p_sheo_2.png"
P[r_dexter]="$H A tidy sunny Miami police forensic lab: microscopes, glass slides, a window showing palm trees and the sea. A neat polite forensic analyst with short dark hair in a short-sleeved patterned shirt holds an open box of donuts in one hand and a magnifying glass in the other, studying pink raspberry jam splatters mixed with birthday cake crumbs and colorful candles stuck on the hero's armor. In the background, a small room covered in clear plastic sheeting. $ST"
P[r_wabbajack]="$H The hero proudly holds up with one hand a long twisted magical wooden staff topped with a grinning jester mask, half purple and half red, with little bells, crackling with purple and orange sparks of chaotic magic. Around him, mid-transformation inside small puffs of colorful smoke, float a white chicken, a wheel of yellow cheese, a white rabbit and an iced sweetroll pastry. Background: a whimsical mad realm with giant colorful mushrooms and twisted trees under a purple sky. $ST"
ids=("$@"); [ ${#ids} -eq 0 ] && ids=(r_sammax r_indiana r_retour r_kaamelott r_graal r_conan r_stranger r_twinpeaks r_dexter r_wabbajack)
for id in $ids; do
  for s in 1 2; do
    out="${id}_$s.png"; [ -f "$out" ] && continue
    seed=$(( ${#id} * 1000 + s * 71 + 303 ))
    refs=(-i hero.png); [ -n "${R[$id]}" ] && refs+=(-i "${R[$id]}")
    flux-image "${P[$id]}" $refs -s 1280x720 --seed $seed -o "$out" >/dev/null 2>&1
    echo "$(date +%H:%M:%S) ok $out"
  done
done
